// Genuary #19: Op Art

float box2D (vec2 p, float c)
{
    vec2 q = abs(p)-c;
    return min(0., max(q.x,q.y))+length(max(q,0.));
}

float tor(vec3 p, vec2 rh)
{
    vec2 q =vec2(box2D(p.xz,rh.x), p.y);
    return length(q)-rh.y;
}

float SDF (vec3 p)
{return -tor(p, vec2(2., 1.));}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.*fragCoord-iResolution.xy)/iResolution.y;

    vec3 ro = vec3(0.01, 0.01, -2.9), rd=normalize(vec3(uv, 1.)), p=ro,
    col=vec3(0.);
    float shad;
    for (float i=0.; i<100.; i++)
    {
        float d= SDF(p);
        if(d<0.001)
        {
            shad = i/100.;
            break;
        }
        p += d*rd;
    }

    vec2 tuv = vec2(atan(p.x, p.y), p.z+iTime*.5);
    float c = smoothstep(.95,1.3,sin(tuv.y*50.)+1.);
    col = vec3(1.-shad)*c;

    fragColor = vec4(sqrt(col),1.0);
}
